public class GymMembership{static class GymMember{protected String memberId;protected int monthlyFee;private int sessions;private int[] fees=new int[10];private int feeCount;private static int enrolled;private final String membershipNumber;GymMember(String id,int fee){if(id==null||id.trim().length()<4)throw new IllegalArgumentException();memberId=id;monthlyFee=fee;membershipNumber="GYM-"+(++enrolled+2000);}void attendSession(){sessions++;}int getSessionsAttended(){return sessions;}protected void chargeLateFee(int a){fees[feeCount++]=a;}int[] getLateFeeHistory(){return fees.clone();}int getTotalLateFees(){int s=0;for(int i=0;i<feeCount;i++)s+=fees[i];return s;}void payFee(int a){}void payFee(int a,String m){payFee(a);}static int getMembersEnrolled(){return enrolled;}}static class PremiumMember extends GymMember{PremiumMember(String i,int f){super(i,f);}@Override protected void chargeLateFee(int a){super.chargeLateFee(a/2);}}static class EliteMember extends PremiumMember{EliteMember(String i,int f){super(i,f);}}static class GroupClassMember extends GymMember{GroupClassMember(String i,int f){super(i,f);}}static boolean isValidReferralCode(String c){return c!=null&&c.length()==4&&c.charAt(0)=='G'&&Character.isDigit(c.charAt(1))&&Character.isDigit(c.charAt(2))&&Character.isUpperCase(c.charAt(3));}static String processWeeklyCheckIn(GymMember[] a){int p=0,n=0,g=0;for(GymMember m:a){if(m==null){n++;continue;}p++;if(m instanceof GroupClassMember)g++;}return p+" processed | "+n+" null skipped | "+g+" group | "+(p-g)+" individual";}}